/* MCN 公会 · 商业化完善层：在 mcn-promotion.js 之后加载。补全业务规则与状态、整合 V23 导航，
   并以统一的 V23 设计重做用户端公会 / 推广页面。原有命令、资金快照与后台审核口径保持不变。 */
const MCNX={inviteDays:7};
const MCNX_LIVE=['已生效','离会待审'],MCNX_PENDING=['待服务者确认','待公会确认'],MCNX_CLOSED_RECRUIT=['已拒绝','已结束','已撤回','已过期','已签约'];
function mcnxManaged(u=feAuthUser()){return u?mcnDB().guilds.find(g=>g.manager===u.id&&g.status!=='已关闭')||null:null;}
function mcnxContract(pid){return pid?mcnDB().contracts.find(c=>c.provider===pid&&MCNX_LIVE.includes(c.status)&&c.to>=TODAY)||null:null;}
function mcnxProviderOf(uid){return db.providers.find(p=>p.uid===uid)||null;}
function mcnxDaysLeft(to){return !to||to>='9999-12-31'?Infinity:Math.round((Date.parse(to+'T00:00:00Z')-Date.parse(TODAY+'T00:00:00Z'))/86400000);}
function mcnxTerm(c){return !c.to||c.to>='9999-12-31'?'长期有效':(c.from?c.from+' 至 ':'至 ')+c.to;}
function mcnxTermTo(term,g){if(term===undefined||term==='')return mcnDeadline(g.contractDays);const n=Number(term);demand(Number.isInteger(n)&&n>=0&&n<=1095,'请选择合作期限');return n===0?'9999-12-31':pd8AddDays(TODAY,n);}
function mcnxAvatar(name,cls=''){return `<span class="mcnx-ava ${cls}" aria-hidden="true">${e([...String(name||'公')][0])}</span>`;}
function mcnxPill(s){const t=String(s||'');const cls=/^(正常|已生效|已签约|有效推广|已缴纳|已到账|启用|可结算|已结清|招募中|接单中)$/.test(t)?'green':/(拒绝|驳回|暂停|关闭|失败|解除|失效|过期|追回|未达标|到期)/.test(t)?'red':/(待|中|未知|在途|保全|补件|结算期)/.test(t)?'amber':'';return `<span class="fe-pill ${cls}">${e(t)}</span>`;}
function mcnxBtn(action,label,id='',values={},cls='small',open=false){return `<button type="button" class="fe-btn ${cls}" data-mcn-${open?'open':'command'}="${e(action)}" data-id="${e(id)}" data-values="${e(JSON.stringify(values))}">${label}</button>`;}
function mcnxHelp(page){return `<div class="mcn-helpbar">${mcnHelpButton('front:'+page)}</div>`;}
function mcnxMoney(n){const v=Number(n||0);return fxPricingCode()+' '+v.toLocaleString('en-US',{minimumFractionDigits:Number.isInteger(v)?0:2,maximumFractionDigits:2});}
function mcnxKpis(items){return `<section class="mcnx-kpis">${items.map(([l,v,i,sub])=>`<div><span class="v23-tile v23-tile-${i}">${v23I(i)}</span><span><b>${e(v)}</b><small>${e(l)}</small>${sub?`<em>${e(sub)}</em>`:''}</span></div>`).join('')}</section>`;}
function mcnxPanel(title,body,side='',icon=''){return `<section class="v23-panel mcnx-panel"><div class="v23-sec-head"><h3>${icon?v23I(icon):''}${e(title)}</h3>${side}</div>${body}</section>`;}
function mcnxInviteUrl(code){const base=/^https?:$/.test(location.protocol||'')?location.origin+location.pathname:'https://banyu.example/';return base+'?invite='+encodeURIComponent(code);}
function mcnxCode(code){return String(code||'').replace(/^MCNCODE/,'').match(/.{1,4}/g)?.join(' ')||code;}
function mcnxGuildTodos(g){const d=mcnDB();return {joins:d.contracts.filter(c=>c.guild===g.id&&c.status==='待公会确认'),invites:d.contracts.filter(c=>c.guild===g.id&&c.status==='待服务者确认'),recruits:d.recruits.filter(r=>r.guild===g.id&&['待用户确认','已接受 · 待入驻','入驻申请中','待签约'].includes(r.status)),leaves:d.contracts.filter(c=>c.guild===g.id&&c.status==='离会待审')};}
function mcnxMyInvites(u){const d=mcnDB(),p=mcnxProviderOf(u.id);return {recruits:d.recruits.filter(r=>r.user===u.id&&r.status==='待用户确认'),onboarding:d.recruits.filter(r=>r.user===u.id&&['已接受 · 待入驻','入驻申请中'].includes(r.status)),contracts:p?d.contracts.filter(c=>c.provider===p.id&&c.status==='待服务者确认'):[],applied:p?d.contracts.filter(c=>c.provider===p.id&&c.status==='待公会确认'):[]};}
function mcnxEligibleJoin(g,u=feAuthUser()){const p=feProvider();if(!u||!p||g.status!=='正常'||g.recruitOpen===false||g.stationId!==u.stationId||g.manager===u.id||mcnxManaged(u)||mcnxContract(p.id))return false;return !mcnDB().contracts.some(c=>c.provider===p.id&&MCNX_PENDING.includes(c.status));}

/* ---------- Rules: validation, new actions and state completion ---------- */
function mcnxCommand(action,id,data,backend){
 let site='',actor='';const reason=String(data.reason||'用户端本地演示操作').trim();
 if(action==='contractTerminate'){const a=admin19Require(true);demand(FE.mode==='admin'||ADMIN19.backendDepth>0,'请在运营后台处理管理动作');demand(reason.length>=4,'请填写至少4字处理依据');const c=mcnGet('contracts',id);demand(MCNX_LIVE.includes(c.status),'仅可解除生效中或离会待审的签约');c.status='已解除';c.endedAt=mcnNow();c.terminateReason=reason;c.terminatedBy=a.subject;site=c.stationId;actor=a.subject;}
 else{demand(FE.mode!=='admin','用户端动作须使用独立用户端身份');const u=mcnUser();actor=u.id;site=u.stationId;
  if(action==='recruitCancel'){const r=mcnGet('recruits',id);mcnOwnGuild(r.guild);demand(r.status==='待用户确认','对方已处理该邀请，无法撤回');r.status='已撤回';r.endedAt=mcnNow();}
  else if(action==='leaveCancel'){const c=mcnGet('contracts',id),g=mcnGet('guilds',c.guild);demand(c.status==='离会待审','当前没有待审的离会申请');demand([c.user,g.manager].includes(u.id),'无权撤回此离会申请');demand(!c.leaveBy||c.leaveBy===u.id,'只有离会发起方可以撤回');c.status='已生效';c.leaveCancelledAt=mcnNow();delete c.leaveAfter;delete c.leaveAt;delete c.demoCoolingElapsed;}
  else if(action==='recruitToggle'){const g=mcnOwnGuild(id);demand(g.status==='正常','公会当前状态不可调整招募');g.recruitOpen=g.recruitOpen===false;}
  else demand(false,'未知公会操作');}
 mcnSyncShares();mcnLog(action,id,reason,site,actor);return id;}
const mcnxCommandBase=mcnCommand;
mcnCommand=function(action,id='',data={},backend=false){
 const d=mcnDB();
 if(['contractTerminate','recruitCancel','leaveCancel','recruitToggle'].includes(action))return mcnxCommand(action,id,data,backend);
 if(action==='inviteAny'){const g=mcnOwnGuild(id),member=getBy('users',data.user);demand(member,'请选择邀请对象');const p=mcnxProviderOf(member.id),payload={pct:data.pct,to:mcnxTermTo(data.term,g),reason:data.reason};return p&&p.skill==='已通过'?mcnCommand('invite',g.id,{...payload,provider:p.id}):mcnCommand('recruit',g.id,{...payload,user:member.id});}
 if(!backend){
  if(action==='guildApply'){const u=mcnUser(),name=String(data.name||'').trim(),p=feProvider();demand(name.length<=30,'公会名称最多30个字');demand(!d.guilds.some(g=>g.status!=='已关闭'&&g.stationId===u.stationId&&g.name===name),'本站已有同名公会，请换一个名称');demand(!(p&&mcnxContract(p.id)),'你已签约其他公会，需离会后才能创建自己的公会');}
  if(action==='recruit'){const member=getBy('users',data.user),p=member&&mcnxProviderOf(member.id);if(member){demand(!(p&&mcnxContract(p.id)),'对方已签约公会，需先在原公会完成离会');demand(!d.guilds.some(g=>g.manager===member.id&&g.status!=='已关闭'),'对方是其他公会的管理者，不能招募为成员');}}
  if(action==='invite'){const p=getBy('providers',data.provider);if(p)demand(!d.guilds.some(g=>g.manager===p.uid&&g.status!=='已关闭'),'对方是其他公会的管理者，不能签约为成员');}
  if(action==='joinApply'){const g=mcnGet('guilds',id),u=mcnUser();demand(g.recruitOpen!==false,'该公会暂未开放入会申请');demand(!d.guilds.some(x=>x.manager===u.id&&x.status!=='已关闭'),'公会管理者不能以服务者身份加入其他公会');}
  if(action==='recruitAccept'){const r=mcnGet('recruits',id),u=mcnUser();demand(!r.expiresAt||r.expiresAt>=TODAY,'邀请已过期，请联系公会重新发送');demand(!d.guilds.some(g=>g.manager===u.id&&g.status!=='已关闭'),'你已是公会管理者，不能再加入其他公会');}
 }
 const out=mcnxCommandBase(action,id,data,backend);
 if(action==='recruit')mcnGet('recruits',out).expiresAt=pd8AddDays(TODAY,MCNX.inviteDays);
 if(['invite','joinApply','amend'].includes(action))mcnGet('contracts',out).expiresAt=pd8AddDays(TODAY,MCNX.inviteDays);
 if(action==='leave'){const c=mcnGet('contracts',id);if(!c.leaveBy)c.leaveBy=feAuthUser()?.id||'';}
 if(action==='sign'){const c=mcnGet('contracts',id);if(c.status==='已生效'){for(const x of d.contracts)if(x.id!==c.id&&x.provider===c.provider&&MCNX_PENDING.includes(x.status)){x.status='已失效';x.reason='服务者已与其他公会签约';}for(const r of d.recruits)if(r.user===c.user&&r.guild!==c.guild&&r.status==='待用户确认'){r.status='已结束';r.note='对方已签约其他公会';}}}
 return out;};
function mcnxSync(){const d=mcnDB();
 for(const r of d.recruits){const g=d.guilds.find(x=>x.id===r.guild);if(r.status==='待用户确认'){if(r.expiresAt&&r.expiresAt<TODAY)r.status='已过期';else if(g?.status==='已关闭'){r.status='已结束';r.note='公会已关闭';}}
  if(r.status==='待签约'&&r.contract){const c=d.contracts.find(x=>x.id===r.contract);if(c&&['已拒绝','已失效','已解除','已退出','已到期'].includes(c.status))r.status='已结束';}}
 for(const c of d.contracts){if(MCNX_PENDING.includes(c.status)&&c.expiresAt&&c.expiresAt<TODAY){c.status='已失效';c.reason='邀请超过有效期';}if(c.status==='已生效'&&c.to<TODAY){c.status='已到期';c.endedAt=mcnNow();}}
 for(const g of d.guilds)if(g.status==='已关闭')for(const p of d.promoters)if(p.kind==='guild'&&p.owner===g.id&&p.status==='启用'){p.status='已关闭';p.closedReason='公会已关闭，机构推广随之停止';}}
const mcnxSyncBase=mcnSyncRecruits;mcnSyncRecruits=function(){const out=mcnxSyncBase();mcnxSync();return out;};
const mcnxExitBase=mcnExitCheck;
mcnExitCheck=function(g){mcnxExitBase(g);const p=mcnPromoter('guild',g.id);if(!p)return;const q=mcnEarnings('promotion',p.id);demand(!mcnDB().withdrawals.some(w=>w.owner===p.id&&w.kind==='promotion'&&!['已到账','已驳回','已取消'].includes(w.status)),'机构推广收益提款尚未完结');demand(!q.recovery,'机构推广收益有待追回款项');demand(cents(addMoney(q.total,-q.paid))===0,'机构推广仍有未结清收益（含待结算），请结清后再退出');};
function mcnxExitChecklist(g){const d=mcnDB(),bids=db.bills.filter(b=>b.mcnSnapshot?.guild?.id===g.id),promo=mcnPromoter('guild',g.id),pq=promo&&mcnEarnings('promotion',promo.id);return [
 ['签约与邀请已处理',!d.contracts.some(c=>c.guild===g.id&&['已生效','离会待审','待服务者确认','待公会确认'].includes(c.status))],
 ['关联订单履约与售后已完结',!bids.some(b=>pd8LiveStops(b.id).length||db.fulfillments.some(f=>f.bill===b.id&&!['已确认','已取消','已完成'].includes(f.status)))],
 ['保障案件已结案',!d.claims.some(c=>c.guild===g.id&&['待受理','已冻结','待赔付'].includes(c.status))],
 ['公会收益提款已完结、无待追回',!d.withdrawals.some(w=>w.owner===g.id&&w.kind==='guild'&&!['已到账','已驳回','已取消'].includes(w.status))&&!mcnEarnings('guild',g.id).recovery],
 ['没有结果未知的保证金支付',!d.depositPayments.some(p=>p.guild===g.id&&p.status==='结果未知')],
 ['机构推广收益已结清',!pq||cents(addMoney(pq.total,-pq.paid))===0]];}
const mcnxContractRowBase=mcnContractRow;
mcnContractRow=function(c,backend=false){const row=mcnxContractRowBase(c,backend);if(backend&&admin19Bound()?.role==='admin'&&MCNX_LIVE.includes(c.status))row[4]=(row[4]==='查看记录'?'':row[4])+mcnBtn('contractTerminate','平台解除签约',c.id,{},true,true);if(c.status==='已解除')row[3]=e('平台解除：'+(c.terminateReason||''));return row;};
const mcnxOpenBase=mcnOpenForm;
mcnOpenForm=function(action,id,values={},backend=false){
 const reason=(label='操作依据（至少4字）',v='')=>mcnField('reason',label,v);
 if(action==='contractTerminate'){const c=mcnGet('contracts',id);return mcnDialog('平台解除签约',mcnForm(action,id,`<p>${e(providerName(c.provider))} · ${e(mcnGet('guilds',c.guild).name)} · 分成 ${c.pct}%</p><p class="mcn-rule-note">用于违规、纠纷或资质失效等平台处置。解除后不再为新账单保存公会分成；已成交订单按原快照继续履约、结算与售后。</p>`+reason('解除依据（至少4字）'),'确认解除',true));}
 if(action==='leave'&&!backend){const c=mcnGet('contracts',id),days=mcnDB().settings.coolingDays;return mcnDialog('申请离会 / 解约',mcnForm(action,id,`<p>${e(mcnGet('guilds',c.guild).name)} · ${e(providerName(c.provider))} · 分成 ${c.pct}%</p><ul class="fe-rule-list"><li>提交后进入“离会待审”，冷静期 ${days} 天，期间不再为新订单保存公会分成</li><li>原订单的履约与售后完结后，由平台核验并生效</li><li>冷静期内发起方可以撤回申请，签约恢复</li></ul>`+mcnField('reason','离会原因（至少4字）',''),'提交离会申请'));}
 if(action==='guildExit'){const g=mcnOwnGuild(id),list=mcnxExitChecklist(g);return mcnDialog('申请退出公会',mcnForm(action,id,`<ul class="mcnx-check">${list.map(([t,ok])=>`<li class="${ok?'ok':'no'}">${v23I(ok?'check':'close')}${e(t)}</li>`).join('')}</ul><p class="mcn-rule-note">${mcnDeposit(g.id).total>0?'有剩余保证金时进入“退出中”，再申请原路退还，退还到账后公会关闭。':'没有剩余保证金，确认后公会直接关闭。'}</p>`+mcnField('reason','退出原因（至少4字）',''),'确认申请退出'));}
 return mcnxOpenBase(action,id,values,backend);};
MCN_HELP.mcnGuilds.fields['招募开关']='公会可暂停或开放入会申请；暂停后公会广场不显示申请入口，已发出的邀请不受影响。';
MCN_HELP.mcnGuilds.fields['邀请有效期']='招募与签约邀请发出后 '+MCNX.inviteDays+' 天内有效，过期需重新邀请；被邀请方签约其他公会后，其余待确认邀请自动失效。';
MCN_HELP.mcnGuilds.fields['平台解除']='总站对违规、纠纷或资质失效的签约执行解除；仅影响之后的新账单，历史成交快照不变。';

/* ---------- Shell integration: navigation, overlays, feedback ---------- */
const mcnxSideBase=mcnSideBefore;
function mcnxSideItem(page,label,icon,badge=0){return `<button type="button" class="v23-side-item ${FE.page===page?'active':''}" data-fe="go" data-id="${page}|">${v23I(icon)}<span>${label}</span>${v23Badge(badge)}</button>`;}
v23SideMenu=function(){const html=mcnxSideBase(),u=feAuthUser();if(!u)return html;const g=mcnxManaged(u),p=feProvider(),c=p&&mcnxContract(p.id),promo=mcnPromoter('user',u.id)||(g&&mcnPromoter('guild',g.id)),todo=v23Todos().filter(t=>t.mcn).length;
 const items=g?[mcnxSideItem('mcn','公会概览','grid'),mcnxSideItem('mcnTeam','成员与签约','users',todo),mcnxSideItem('mcnIncome','公会收益','wallet'),mcnxSideItem('mcnDeposit','保证金','shield'),mcnxSideItem('promotion','会员推广','spark')]:[mcnxSideItem('mcn',c?'我的公会':'公会中心','grid'),mcnxSideItem('mcnTeam','签约与邀请','users',todo),mcnxSideItem('guilds','公会广场','compass'),mcnxSideItem('promotion','会员推广','spark')];
 if(promo)items.push(mcnxSideItem('promotionIncome','推广收益','wallet'));
 const group=`<div class="v23-side-group"><span>公会与推广</span>${items.join('')}</div>`,first=html.indexOf('<div class="v23-side-group">'),second=first>=0?html.indexOf('<div class="v23-side-group">',first+10):-1,at=(g||c)&&second>=0?second:html.indexOf('<div class="v23-side-group"><span>账户</span>');return at>=0?html.slice(0,at)+group+html.slice(at):html+group;};
function mcnxPlace(id){if(FE.mode==='admin')return;const el=document.getElementById(id),host=FE.mode==='h5'?document.querySelector('#feRoot .fe-phone'):document.getElementById('feRoot');if(el&&host){host.appendChild(el);el.classList.toggle('in-phone',FE.mode==='h5');}}
const mcnxDialogBase=mcnDialog;mcnDialog=function(...args){const out=mcnxDialogBase(...args);mcnxPlace('mcn-dialog-root');return out;};
const mcnxHelpBase=mcnShowHelp;mcnShowHelp=function(...args){const out=mcnxHelpBase(...args);mcnxPlace('mcn-help-root');return out;};
const MCNX_MSG={guildApply:id=>{const g=mcnGet('guilds',id);return g.status==='正常'?'公会已创建，现在可以邀请成员':g.status==='待审核'?'公会申请已提交，等待平台审核':'公会已创建，请先缴纳最低保证金';},guildResubmit:()=>'材料已补充，重新进入平台审核',guildProfile:()=>'公会资料已保存',recruitToggle:id=>mcnGet('guilds',id).recruitOpen===false?'已暂停入会申请':'已开放入会申请',
 recruit:()=>'招募邀请已发送，等待对方确认',inviteAny:id=>mcnDB().recruits.some(r=>r.id===id)?'招募邀请已发送，等待对方确认':'签约邀请已发送，等待对方确认',invite:()=>'签约邀请已发送，等待对方确认',recruitCancel:()=>'邀请已撤回',recruitAccept:()=>feProvider()?'已接受邀请，请确认签约条款':'已接受邀请，请完成服务者入驻资料',recruitDecline:()=>'已拒绝邀请',joinApply:()=>'入会申请已提交，等待公会确认',
 sign:id=>mcnGet('contracts',id).replaces?'新的分成条款已生效':'签约已生效',decline:()=>'已拒绝 / 撤回该签约邀请',amend:()=>'分成变更已发出，对方确认后生效',leave:()=>'离会申请已提交，冷静期结束且原订单完结后由平台核验',leaveCancel:()=>'已撤回离会申请，签约继续有效',
 depositCreate:()=>'保证金待支付单已生成，请选择模拟支付结果',depositResult:id=>({已缴纳:'保证金缴纳成功',支付失败:'支付失败，可以重新发起缴纳',结果未知:'支付结果未知，请稍后查询原支付请求'})[mcnGet('depositPayments',id).status]||'保证金状态已更新',claimApply:()=>'保障申请已提交，等待平台核定',guildExit:id=>mcnGet('guilds',id).status==='已关闭'?'公会已关闭':'已进入退出流程，请申请退还剩余保证金',
 activatePromotion:()=>'推广已开启，复制邀请链接分享给好友吧',payee:()=>'结算账户已更新，需重新核验',withdraw:()=>'提现申请已提交，等待平台审核',withdrawCancel:()=>'提现申请已撤销，金额已释放',contractTerminate:()=>'签约已由平台解除',guildReview:()=>'公会审核结果已保存',guildStatus:()=>'公会经营状态已更新'};
function mcnxNext(action){if(action==='guildApply')return ['mcn'];if(action==='recruitAccept')return feProvider()?['mcnTeam']:['apply'];if(action==='joinApply')return ['mcnTeam'];return null;}
function mcnxCopy(action,code){const p=mcnDB().promoters.find(x=>x.code===code);demand(p&&p.user===mcnUser().id,'仅能复制本人的邀请码');const text=action==='copyCode'?code:mcnxInviteUrl(code),done=()=>{FE.flash=action==='copyCode'?'邀请码已复制':'邀请链接已复制';feRender();},fallback=()=>mcnDialog(action==='copyCode'?'邀请码':'邀请链接',`<code class="mcn-copy">${e(text)}</code><p>浏览器不允许自动复制，请长按或选中后手动复制。</p>`);if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(done).catch(fallback);else fallback();}
function mcnxQr(code,size=168){try{return qrSvg(mcnxInviteUrl(code),size).replace('aria-label="代理推广二维码"','aria-label="会员邀请二维码"');}catch{return '';}}
function mcnxPoster(code){const p=mcnDB().promoters.find(x=>x.code===code);demand(p&&p.user===mcnUser().id,'仅能下载本人的邀请海报');const name=p.kind==='guild'?p.name:v23Name(getBy('users',p.user)),qr=mcnxQr(code,220).replace('<svg ','<svg x="190" y="548" ');
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="600" height="900" viewBox="0 0 600 900"><defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#1d1250"/><stop offset=".6" stop-color="#4a28c4"/><stop offset="1" stop-color="#8b45d8"/></linearGradient></defs><rect width="600" height="900" rx="36" fill="url(#bg)"/><circle cx="520" cy="90" r="140" fill="#ffffff" opacity=".07"/><g font-family="PingFang SC,Microsoft YaHei,sans-serif" fill="#fff"><text x="48" y="92" font-size="30" font-weight="700">伴屿</text><text x="48" y="210" font-size="40" font-weight="800">${e(name)}</text><text x="48" y="262" font-size="30" font-weight="700">邀请你加入伴屿</text><text x="48" y="318" font-size="22" opacity=".82">游戏搭子 · 生活倾听 · 学习陪伴</text><text x="48" y="358" font-size="22" opacity=".82">认证服务者，先试听再预约，售后可追溯</text></g><rect x="170" y="528" width="260" height="260" rx="22" fill="#fff"/>${qr}<g font-family="PingFang SC,Microsoft YaHei,sans-serif" fill="#fff" text-anchor="middle"><text x="300" y="836" font-size="24" font-weight="700">邀请码 ${e(mcnxCode(code))}</text><text x="300" y="870" font-size="16" opacity=".7">本地交互原型 · 虚构演示</text></g></svg>`;
 safeDownload(svg,'伴屿邀请海报-'+code+'.svg','image/svg+xml');FE.flash='邀请海报已下载';feRender();}
mcnRun=function(action,id,data={},backend=false){
 V23.flashErr=false;
 try{
  if(action==='chooseKind'||action==='promoteAs'){mcnUser();MCN.promoKind=data.kind==='guild'?'guild':'user';return action==='promoteAs'?feNavigate('promotion'):feRender();}
  if(action==='copyInvite'||action==='copyCode')return mcnxCopy(action,id);
  if(action==='downloadPoster')return mcnxPoster(id);
  if(action==='export'){admin19Require();const f=mcnReportFacts(),csv=[['时间UTC','事件','对象','会员','站点','来源'],...f.events.map(x=>[x.at,x.type,x.object,x.user,x.stationId,x.source])].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');return c21DownloadReport(csv,'公会与推广本地事件.csv');}
  const out=v22Persist(()=>mcnCommand(action,id,data,backend));
  mcnCloseDialog();
  if(action==='visit'){MCN.pendingCode=mcnDB().promoters.find(p=>p.code===id).code;return feNavigate('register');}
  const msg=MCNX_MSG[action]?.(out,data)||'本地公会 / 推广操作已保存';
  if(backend){toast(msg);render();return out;}
  const next=mcnxNext(action);if(next)feNavigate(next[0],next[1]||'');
  FE.flash=msg;feRender();return out;
 }catch(err){V23.flashErr=true;throw err;}};
V23_TODO_SOURCES.push(u=>{mcnEnsure();const out=[],mi=mcnxMyInvites(u),gname=id=>mcnGet('guilds',id).name;
 for(const r of mi.recruits)out.push({mcn:true,icon:'users',tag:'公会招募',title:gname(r.guild)+' 邀请你成为签约服务者',text:`公会分成 ${r.pct}% · ${r.to>='9999-12-31'?'长期合作':'合作至 '+r.to}${r.expiresAt?' · 邀请有效至 '+r.expiresAt:''}`,actions:mcnxBtn('recruitAccept','接受',r.id,{},'small primary')+mcnxBtn('recruitDecline','拒绝',r.id)});
 for(const r of mi.onboarding)out.push({mcn:true,icon:'doc',tag:'入驻',title:'完成服务者入驻资料',text:gname(r.guild)+' 的招募已接受，提交入驻资料后确认签约',page:'apply'});
 for(const c of mi.contracts)out.push({mcn:true,icon:'shield',tag:'签约',title:gname(c.guild)+(c.replaces?' 提出了新的分成条款':' 签约待你确认'),text:`公会分成 ${c.pct}% · ${mcnxTerm(c)}`,actions:mcnxBtn('sign','确认签约',c.id,{},'small primary',true)+mcnxBtn('decline','拒绝',c.id)});
 const g=mcnxManaged(u);if(g)for(const c of mcnxGuildTodos(g).joins)out.push({mcn:true,icon:'users',tag:'入会申请',title:v23Split(providerName(c.provider))[0]+' 申请加入公会',text:`公会默认分成 ${c.pct}% · ${mcnxTerm(c)}`,actions:mcnxBtn('sign','同意签约',c.id,{},'small primary',true)+mcnxBtn('decline','拒绝',c.id)});
 return out;});

/* ---------- Shared page parts ---------- */
function mcnxGuildBar(g,actions=''){return `<section class="mcnx-bar">${mcnxAvatar(g.name,'sm')}<div><b>${e(g.name)}</b><small>${e(siteLabel(g.stationId))} · ${mcnDB().contracts.filter(c=>c.guild===g.id&&MCNX_LIVE.includes(c.status)).length} 名成员</small></div>${mcnxPill(g.status)}<span class="mcnx-bar-actions">${actions}</span></section>`;}
function mcnxGuildHero(g,actions=''){const b=mcnDeposit(g.id),members=mcnDB().contracts.filter(c=>c.guild===g.id&&MCNX_LIVE.includes(c.status)).length,open=g.recruitOpen!==false&&g.status==='正常';
 return `<section class="mcnx-hero">${mcnxAvatar(g.name,'lg')}<div class="mcnx-hero-main"><div class="mcnx-hero-title"><h1>${e(g.name)}</h1>${mcnxPill(g.status)}${g.status==='正常'?(open?'<span class="fe-pill green">招募中</span>':'<span class="fe-pill">暂停招募</span>'):''}</div><p>${e(g.intro||'这家公会还没有填写介绍。')}</p><div class="mcnx-hero-meta"><span>${v23I('pin')}${e(siteLabel(g.stationId))}</span><span>${v23I('users')}${members} 名签约成员</span><span>${v23I('shield')}${b.total>0?'已缴保障金 '+money(b.total):'未缴保障金'}</span><span>${v23I('tag')}默认分成 ${e(g.pct)}%</span></div></div>${actions?`<div class="mcnx-hero-actions">${actions}</div>`:''}</section>`;}
function mcnxTabs(active){return `<nav class="v23-seg mcnx-tabs" aria-label="公会管理">${[['mcn','概览','grid'],['mcnTeam','成员与签约','users'],['mcnIncome','收益结算','wallet'],['mcnDeposit','保证金','shield']].map(([p,t,i])=>`<button type="button" class="${active===p?'active':''}" data-fe="go" data-id="${p}|">${v23I(i)}${t}</button>`).join('')}<button type="button" data-mcn-command="promoteAs" data-id="" data-values="${e(JSON.stringify({kind:'guild'}))}">${v23I('spark')}机构推广</button></nav>`;}
function mcnxStatusAlert(g){const b=mcnDeposit(g.id);
 if(g.status==='待审核')return `<div class="mcnx-alert amber">${v23I('clock')}<div><b>公会申请审核中</b><p>平台审核通过后即可开始招募成员。</p></div></div>`;
 if(g.status==='需补件')return `<div class="mcnx-alert red">${v23I('doc')}<div><b>平台要求补充材料</b><p>${e(g.reviewReason||'请补充机构材料后重新提交审核。')}</p>${mcnForm('guildResubmit',g.id,mcnField('license','补充机构材料引用',g.license||'DEMO-'),'重新提交审核')}</div></div>`;
 if(g.status==='待缴保证金')return `<div class="mcnx-alert amber">${v23I('shield')}<div><b>需缴纳最低保证金后开始经营</b><p>最低要求 ${money(g.depositRequired)}，当前余额 ${money(b.total)}。</p></div>${feGoBtn('去缴纳','mcnDeposit','','small primary')}</div>`;
 if(g.status==='暂停')return `<div class="mcnx-alert red">${v23I('shield')}<div><b>公会已被平台暂停经营</b><p>暂停期间不能招募成员、不为新订单保存公会分成；历史订单与收益不受影响。</p></div></div>`;
 if(g.status==='退出中')return `<div class="mcnx-alert amber">${v23I('logout')}<div><b>公会退出处理中</b><p>剩余保证金退还到账后公会关闭。</p></div>${feGoBtn('保证金与退还','mcnDeposit','','small primary')}</div>`;
 return '';}
function mcnxDenied(title,sub,action=''){return v23Empty(title,sub,action);}
function mcnxMemberRow(c,manage=false){const pr=getBy('providers',c.provider),sh=mcnDB().shares.filter(x=>x.kind==='guild'&&x.owner===c.guild&&x.provider===c.provider),left=mcnxDaysLeft(c.to),u=feAuthUser();
 const term=c.to>='9999-12-31'?'长期':left<=30?`<span class="mcnx-warn">${left} 天后到期</span>`:'至 '+e(c.to);
 let actions=feGoBtn('主页','provider',pr.id,'small');
 if(manage&&c.status==='已生效')actions+=mcnxBtn('amend','调整分成',c.id,{},'small',true)+mcnxBtn('leave','解约',c.id,{},'small',true);
 if(c.status==='离会待审')actions+=(!c.leaveBy||c.leaveBy===u?.id?mcnxBtn('leaveCancel','撤回离会',c.id):'')+`<small class="fe-small">冷静期至 ${e(c.leaveAfter||TODAY)}</small>`;
 return `<div class="v23-member mcnx-member">${feAvatar(pr.uid)}<span class="v23-member-main"><b>${e(v23Split(pr.name)[0])}</b>${genderBadge(pr)}<span class="fe-wrap">${mcnxPill(c.status==='离会待审'?'离会待审':pr.status==='可接单'?'接单中':'暂停接单')}<small class="fe-small">分成 ${e(c.pct)}% · ${term}</small></span></span><span class="mcnx-num"><b>${money(sumMoney(sh,'base'))}</b><small>确认流水</small></span><span class="mcnx-num"><b>${money(sumMoney(sh,'amount'))}</b><small>公会分成</small></span><span class="v23-member-actions">${actions}</span></div>`;}
function mcnxInviteRows(list,empty='暂无记录'){return list.length?`<div class="mcnx-rows">${list.map(x=>`<div class="v23-member">${feAvatar(x.who)}<span class="v23-member-main"><b>${e(x.name)}</b>${genderBadge(x.who)}<span class="fe-wrap">${mcnxPill(x.status)}<small class="fe-small">${e(x.kind)} · 分成 ${e(x.pct)}% · ${e(x.term)}${x.note?' · '+e(x.note):''}</small></span></span><span class="v23-member-actions">${x.actions||''}</span></div>`).join('')}</div>`:`<p class="fe-small">${e(empty)}</p>`;}
function mcnxManagerInvites(g){const d=mcnDB(),rows=[];
 for(const r of d.recruits.filter(r=>r.guild===g.id&&!MCNX_CLOSED_RECRUIT.includes(r.status))){const c=r.contract&&d.contracts.find(x=>x.id===r.contract);rows.push({who:r.user,name:v23Name(getBy('users',r.user)),status:r.status,kind:'招募入驻',pct:r.pct,term:r.to>='9999-12-31'?'长期':'至 '+r.to,note:r.status==='待用户确认'&&r.expiresAt?'邀请有效至 '+r.expiresAt:r.status==='待签约'?'等待对方确认签约':['已接受 · 待入驻','入驻申请中'].includes(r.status)?'等待对方提交入驻资料':'',actions:r.status==='待用户确认'?mcnxBtn('recruitCancel','撤回',r.id):c&&c.status==='待服务者确认'?mcnxBtn('decline','撤回',c.id):''});}
 for(const c of d.contracts.filter(c=>c.guild===g.id&&MCNX_PENDING.includes(c.status)&&!c.recruit)){const pr=getBy('providers',c.provider);rows.push({who:pr?.uid,name:v23Split(pr?.name||c.provider)[0],status:c.status,kind:c.status==='待公会确认'?'入会申请':c.replaces?'分成变更':'签约邀请',pct:c.pct,term:mcnxTerm(c),note:c.expiresAt?'有效至 '+c.expiresAt:'',actions:c.status==='待公会确认'?mcnxBtn('sign','同意签约',c.id,{},'small primary',true)+mcnxBtn('decline','拒绝',c.id):mcnxBtn('decline','撤回',c.id)});}
 return rows;}
