 const invites=[...mi.recruits.map(r=>({who:mcnGet('guilds',r.guild).manager,name:mcnGet('guilds',r.guild).name,status:'待你确认',kind:'招募邀请',pct:r.pct,term:r.to>='9999-12-31'?'长期':'至 '+r.to,note:r.expiresAt?'有效至 '+r.expiresAt:'',actions:mcnxBtn('recruitAccept','接受',r.id,{},'small primary')+mcnxBtn('recruitDecline','拒绝',r.id)})),...mi.contracts.map(x=>({who:mcnGet('guilds',x.guild).manager,name:mcnGet('guilds',x.guild).name,status:'待你确认',kind:x.replaces?'分成变更':'签约邀请',pct:x.pct,term:mcnxTerm(x),actions:mcnxBtn('sign','确认签约',x.id,{},'small primary',true)+mcnxBtn('decline','拒绝',x.id)})),...mi.applied.map(x=>({who:mcnGet('guilds',x.guild).manager,name:mcnGet('guilds',x.guild).name,status:'待公会确认',kind:'入会申请',pct:x.pct,term:mcnxTerm(x),actions:mcnxBtn('decline','撤回申请',x.id)}))];
 if(mi.onboarding.length)html+=`<div class="mcnx-alert amber">${v23I('doc')}<div><b>完成服务者入驻资料</b><p>${e(mcnGet('guilds',mi.onboarding[0].guild).name)} 的招募已接受。提交入驻资料后${mcnDB().settings.recruitApprovalRequired?'等待平台审核，':''}即可确认签约。</p></div>${feGoBtn('去填写','apply','','small primary')}</div>`;
 if(invites.length||focus==='mcnTeam')html+=mcnxPanel('邀请与申请',mcnxInviteRows(invites,'暂无公会邀请或入会申请'),'','bell');
