 const invite=`<section class="mcnx-invite"><div class="mcnx-invite-main"><small>我的邀请码</small><div class="mcnx-code">${e(mcnxCode(p.code))}</div><code class="mcn-copy">${e(mcnxInviteUrl(p.code))}</code><div class="fe-wrap">${mcnxBtn('copyInvite','复制邀请链接',p.code,{},'primary')}${mcnxBtn('copyCode','复制邀请码',p.code,{},'')}${mcnxBtn('downloadPoster','下载邀请海报',p.code,{},'')}${feGoBtn('预览邀请页','invite',p.code,'v23-link')}</div><p class="fe-small">推广资格：${e(p.status)} · 链接仅在同一浏览器的本地演示数据中生效。</p></div>${qr?`<div class="mcnx-qr">${qr}<small>扫码打开邀请页</small></div>`:''}</section>`;
