FE_PAGES.v22Studio=function(){const p=feProvider(),c=p&&mcnxContract(p.id),inv=feAuthUser()?mcnxMyInvites(feAuthUser()):{contracts:[],recruits:[]},card=p?mcnxPanel(c?'我的公会':'公会合作',c?`<button type="button" class="v23-row" data-fe="go" data-id="mcn|">${mcnxAvatar(mcnGet('guilds',c.guild).name,'sm')}<span><b>${e(mcnGet('guilds',c.guild).name)}</b><small>分成 ${e(c.pct)}% · ${e(mcnxTerm(c))}${c.status==='离会待审'?' · 离会待审':''}</small></span>${v23I('right','v23-row-arrow')}</button>`:`<p class="fe-small">${inv.contracts.length?'你有 '+inv.contracts.length+' 份签约邀请待确认。':'签约公会可获得培训、质量协助与服务保障。'}</p>${feGoBtn(inv.contracts.length?'处理邀请':'浏览公会',inv.contracts.length?'mcnTeam':'guilds','','small primary')}`,'','users'):'';return mcnxHelp('v22Studio')+v23StudioPage().replace('<aside>','<aside>'+card);};
