/* After invited onboarding, continue straight to the contract confirmation step. */
const mcnxSubmitBase=feSubmit;
feSubmit=function(type,id,fd){const out=mcnxSubmitBase(type,id,fd);if(type==='apply'&&FE.mode!=='admin'&&FE.page==='apply'){const u=feAuthUser(),c=u&&feProvider()&&mcnxMyInvites(u).contracts[0];if(c){feNavigate('mcnTeam');FE.flash='已成为服务者，请确认公会签约条款，再完善商品与档期';feRender();}}return out;};
/* Order / funds / earnings: show each party only what concerns them. */
function mcnxOrderExtra(o){const u=feAuthUser();if(!o||!u)return '';const provider=getBy('providers',o.provider),isProvider=provider?.uid===u.id,isBuyer=o.buyer===u.id;if(!isProvider&&!isBuyer)return '';
 const bills=db.bills.filter(b=>b.order===o.id&&b.mcnSnapshot?.guild),claims=mcnDB().claims.filter(c=>c.order===o.id&&(isProvider||c.user===u.id));if(!bills.length&&!claims.length)return '';
 const g=bills[0]&&mcnDB().guilds.find(x=>x.id===bills[0].mcnSnapshot.guild.id);
 if(isProvider){const rows=mcnDB().shares.filter(x=>x.order===o.id&&x.kind==='guild').map(x=>`<div class="v23-row v23-row-static">${v23I('wallet')}<span><b>毛收益 ${money(x.base)} → 公会 ${money(x.amount)} → 你的净收益 ${money(addMoney(x.base,-x.amount))}</b><small>${e(x.bill)} · 成交时签约比例 ${e(x.pct)}% · ${e(x.status)}</small></span></div>`).join('');
  return mcnxPanel('公会分成',(rows||`<p class="fe-small">本单成交时签约 ${e(g?.name||'公会')}（${e(bills[0]?.mcnSnapshot.guild.pct)}%），买家确认履约后按成交快照生成公会分成。</p>`)+(claims.length?mcnClaimsTable(claims):''),'','users');}
 const b=g?mcnDeposit(g.id):null,stops=db.stops.filter(c=>c.order===o.id&&c.status==='已执行'&&getBy('bills',c.bill)?.mcnSnapshot?.guild&&!mcnDB().claims.some(x=>x.case===c.id&&x.status!=='已驳回'));
 return mcnxPanel('公会服务保障',`<p class="fe-small">本服务者签约 ${e(g?.name||'公会')}${b?.total>0?'，公会已缴保障金 '+money(b.total):''}。订单退款与售后由平台按原订单处理；售后核定后仍有损失的，可申请公会额外保障补偿，不影响原退款。</p>${claims.length?mcnClaimsTable(claims):''}${stops.map(c=>mcnBtn('claimApply','申请额外保障补偿',c.id,{},false,true)).join('')}`,'','shield');}
FE_PAGES.order=()=>mcnxHelp('order')+mcnOrderPageBefore()+mcnxOrderExtra(getBy('orders',FE.id));
FE_PAGES.funds=()=>{const claims=mcnDB().claims.filter(c=>c.user===FE.user);return mcnxHelp('funds')+mcnFundsBefore()+(claims.length?mcnxPanel('公会服务保障补偿',mcnClaimsTable(claims),'','shield'):'');};
FE_PAGES.earnings=()=>{const p=feProvider(),xs=p?mcnDB().shares.filter(x=>x.kind==='guild'&&x.provider===p.id):[],c=p&&mcnxContract(p.id);return mcnxHelp('earnings')+mcnEarningsPageBefore()+(xs.length||c?mcnxPanel('公会分成明细',`<p class="fe-small">${c?'签约 '+e(mcnGet('guilds',c.guild).name)+' · 分成 '+e(c.pct)+'%。':''}服务者可提现金额已扣除公会约定分成；原三方分账展示毛分配，以下逐单记录公会分成。</p>`+mcnShareTable(xs),c?feGoBtn('我的公会 '+v23I('right'),'mcn','','v23-link'):'','users'):'');};
/* Closed institutional promotion cannot be resumed from the back office. */
const mcnxCommandGuard=mcnCommand;
mcnCommand=function(action,id='',data={},backend=false){if(action==='promoterStatus'){const p=mcnGet('promoters',id);demand(p.status!=='已关闭','该机构已关闭，机构推广资格不能恢复');}return mcnxCommandGuard(action,id,data,backend);};
